python3 - <<'PYEOF'
p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/codegen/support/runner.rs'
s = open(p).read()
old = '''            diagnostics.push_str(&body.replace(script_path, &basename));
            diagnostics.push('\\n');'''
new = '''            // The MESSAGE only. php ends every diagnostic with ` in <file> on line <n>`, which is
            // produced by one runtime path and pinned by tests of its own; repeating it in every
            // assertion that cares about a wording would add a line number to maintain and no
            // coverage. A test that wants the location asserts on `stdout` before the split, or
            // on the dedicated location tests.
            let message = match body.find(&needle) {
                Some(cut) => &body[..cut],
                None => body,
            };
            let _ = &basename;
            diagnostics.push_str(message);
            diagnostics.push('\\n');'''
assert old in s, "diagnostics push anchor not found"
s = s.replace(old, new, 1)
open(p, 'w').write(s)
print("diagnostics field carries the message only")
PYEOF
